import{z as l,x as o,o as r,c as d,q as B,j as i,D as E,d as e,s as n,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"软件工程实践收束","description":"","frontmatter":{"title":"软件工程实践收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-map.md","filePath":"cs/swe-map.md","lastUpdated":1791413859000}'),c={name:"cs/swe-map.md"};function p(m,a,h,D,f,C){const t=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="软件工程实践收束" tabindex="-1">软件工程实践收束 <a class="header-anchor" href="#软件工程实践收束" aria-label="Permalink to &quot;软件工程实践收束&quot;">​</a></h1><div class="epigraph"><p>五个环节不是五个工具，是同一条不变式切成的五段：任何时刻，主干上任何快照都能被验证、重建，并送进生产。</p><footer>—— 据 Beck、Chacon-Straub 与交付工程实践整理</footer></div><p><a href="/cs/swe-ci-cd">上一课</a>把三层判据、密封构建与产物晋级装成自动门禁，坏改动从合入前到生产中各有退路。本课程到此收束：把六课连成一条链，指出每两环交接处的不变式，并划出本课程没有覆盖的相邻地带。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把五环节当五个独立工具学，错误全在接缝上：测试挂在没锁版本的依赖上，是测试与构建的缝；产物在每个环境重建，是构建与交付的缝；分支长命不归门禁管，是版本与分支的缝；门禁可以顺手跳过，是制度与制度的缝。收束课要回答的，就是这些缝在哪儿、靠什么焊住。</p><p><span class="marginnote">「缝」可以类比水管的接头：水管理论再漂亮，漏水多半发生在接头而不是管身。五个环节各自学好不难，难的是接缝处的不变式——接头靠垫圈（锁版本、产物不可变、门禁不可跳）压紧，不是靠多拧两圈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走一遍链路。工作区改动先撞上本地判据：单元层毫秒级、属性层持续抽样（<a href="/cs/swe-testing-strategy">测试策略：单元、集成与属性</a>）；提交把行为与判据一起冻进内容寻址的对象库（<a href="/cs/swe-git-internals">git 的内部模型</a>）；短命分支与评审控制相遇成本（<a href="/cs/swe-branching-changes">分支与变更管理</a>）；密封构建把快照变成键控的不可变产物（<a href="/cs/swe-build-systems">构建系统：make 到 bazel</a>）；门禁与合并队列放行，产物逐环境晋级、金丝雀放量（<a href="/cs/swe-ci-cd">CI/CD</a>）。回退不离开这条链：revert 生成反向提交，重建复用缓存，都是链上预留的边。</p>',8)),(r(),i(A,null,{default:E(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%B7%A5%E4%BD%9C%E5%8C%BA%E6%94%B9%E5%8A%A8%22%5D%20--%3E%20T%5B%22%E4%B8%89%E5%B1%82%E5%88%A4%E6%8D%AE%EF%BC%9A%E5%8D%95%E5%85%83%E3%80%81%E9%9B%86%E6%88%90%E3%80%81%E5%B1%9E%E6%80%A7%22%5D%0A%20%20T%20--%3E%20C%5B%22%E5%86%85%E5%AE%B9%E5%AF%BB%E5%9D%80%E6%8F%90%E4%BA%A4%22%5D%0A%20%20C%20--%3E%20B%5B%22%E7%9F%AD%E5%91%BD%E5%88%86%E6%94%AF%E4%B8%8E%E8%AF%84%E5%AE%A1%22%5D%0A%20%20B%20--%3E%20P%5B%22%E5%AF%86%E5%B0%81%E6%9E%84%E5%BB%BA%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%8F%98%E4%BA%A7%E7%89%A9%22%5D%0A%20%20P%20--%3E%20G%5B%22%E9%97%A8%E7%A6%81%E4%B8%8E%E5%90%88%E5%B9%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20G%20--%3E%20D%5B%22%E6%99%8B%E7%BA%A7%E4%B8%8E%E9%87%91%E4%B8%9D%E9%9B%80%22%5D%0A%20%20D%20--%3E%7C%E5%BC%82%E5%B8%B8%7C%20REV%5B%22revert%20%E5%9B%9E%E4%B8%BB%E5%B9%B2%22%5D%0A%20%20REV%20--%3E%20T%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("链条抗腐烂的机理是每一环的失效都有上一环兜住：门禁漏掉的坏改动，由金丝雀与 revert 兜；构建漂移，由内容寻址的键兜；冲突积累，由短命分支兜；行为破坏，由三层判据与属性反例兜。链的强度由最弱一环决定，所以工程重点不是把某一环做到极致，而是让每一环的门禁都不可静默跳过——这是一条串联系统，"),s("a",{href:"/cs/swe-ci-cd"},"CI/CD"),e(" 课的门禁经济学在链上处处适用。")],-1)),(r(),i(A,null,{default:E(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E7%8E%AF%201%EF%BC%9A%E4%B8%89%E5%B1%82%E5%88%A4%E6%8D%AE%22%5D%20--%3E%20M%5B%22%E6%95%B4%E6%9D%A1%E9%93%BE%E7%9A%84%E5%BC%BA%E5%BA%A6%20%3D%20%E6%9C%80%E5%BC%B1%E4%B8%80%E7%8E%AF%22%5D%0A%20%20S2%5B%22%E7%8E%AF%202%EF%BC%9A%E7%89%88%E6%9C%AC%E6%8E%A7%E5%88%B6%22%5D%20--%3E%20M%0A%20%20S3%5B%22%E7%8E%AF%203%EF%BC%9A%E5%88%86%E6%94%AF%E7%AE%A1%E7%90%86%22%5D%20--%3E%20M%0A%20%20S4%5B%22%E7%8E%AF%204%EF%BC%9A%E5%AF%86%E5%B0%81%E6%9E%84%E5%BB%BA%22%5D%20--%3E%20M%0A%20%20S5%5B%22%E7%8E%AF%205%EF%BC%9A%E4%BA%A4%E4%BB%98%E9%97%A8%E7%A6%81%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20E%5B%22%E4%BB%BB%E4%B8%80%E7%8E%AF%E5%8F%AF%E9%9D%99%E9%BB%98%E8%B7%B3%E8%BF%87%EF%BC%9A%E6%95%B4%E6%9D%A1%E9%93%BE%E6%8A%A5%E5%BA%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">串联系统的算术：五环各自 99% 可靠，整条链只有 0.99 的五次方约等于 95.1%。把一环从 99% 磨到 99.9%，收益远不如把最弱的 90% 补到 99%——这就是「重点在均衡、不在极致」的数学根据。</span></p><p><span class="marginnote">初学者容易以为学完五课就「会交付」了。实际上这一课刻意留白：安全供应链、线上可观测、人员流程都在墙外。把收束当路线图而不是完整地图，是读收束课的正确姿势。</span></p><p><span class="marginnote">交接处的不变式可数：判据挂变更集（测试与版本）、历史可回放（版本与分支）、快照可重建（分支与构建）、产物不可变（构建与交付）。审计一条流水线时逐条对这四句，缝在哪儿一目了然。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程没有覆盖的相邻地带：需求与设计方法、流程与人员管理（敏捷仪式不展开）；安全工程与供应链攻击（<a href="/cs/dependency-confusion">依赖混淆</a>、<a href="/cs/sbom-reproducible-builds">SBOM 与可复现构建</a>）；线上的可观测与事件响应（<a href="/cs/distributed-tracing">分布式追踪</a>、<a href="/cs/incident-response">事件响应</a>）。本课程到此收束；深钻层的后续课程按树序继续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>测试、版本、分支、构建、交付是一条链的五段，不变式是「主干随时可验证、可重建、可发布」。</li><li>判据挂变更集：提交里行为与判据同进同出，历史才能回放规格。</li><li>内容寻址贯穿两头：提交对象与构建产物都靠哈希获得身份与完整性。</li><li>门禁的价值在「没过门物理上走不下去」；跳过必须留痕。</li><li>回退是链上预留的边：revert、缓存重建、金丝雀回滚都是常态路径。</li><li>出处：Beck, <em>Test-Driven Development</em>, 2003；Meszaros, <em>xUnit Test Patterns</em>, 2007；Claessen and Hughes, <em>QuickCheck</em>, 2000；Chacon and Straub, <em>Pro Git</em>, 2nd ed., 2014。</li></ul>',7))])}const _=l(c,[["render",p]]);export{F as __pageData,_ as default};
